const e="nys-fair-talent-showcase",c=2025,t="Built from the 2025 booklet only. Printed contact emails are the superintendents' event addresses and are kept as contact Variables. The booklet prints no street address for the venue, no judging criteria, no marks and no points for placings. The online registration link is not printed in the booklet.",n={Title:"Rules & Criteria",Subtitle:"New York State Fair Mini & Maxi Talent Showcase 2025: amateur acts in a Mini and a Maxi division, on {{PreliminaryDates}}.",NoticeTitle:"Please Read Before Registering",Notice:"Acts must be county qualifiers. The fee is {{EntryFee}}, paid online only. Any act over 5 minutes is disqualified.",Notes:["The Talent Showcase aims to encourage, develop and discover amateur entertainers.","Awards are given out after the New York State Fair."],Sections:[{Key:"general",Title:"General",Items:["The New York State Fair Talent Showcase is an annual event that aims to encourage, develop and discover amateur entertainers.","By taking part, contestants agree that their photos may be used in future advertising for the Talent Showcase and the New York State Fair.","The Talent Showcase sponsorship is a non-commercial competition.","The time limit for each act is 5 minutes, including trios. Any act that runs over 5 minutes is disqualified. Acts are timed.","The decision of the judges is final.","The sponsor is not held responsible for the judges' decisions.","An electric piano and a sound system are provided by the Talent Showcase.","There is no rock band contest. No rock bands are scheduled.","Sending an application means that all participants, contestants, chairpeople, teachers and parents accept all terms, rules, regulations and communications of the Talent Showcase."]},{Key:"eligibility",Title:"Who can enter",Items:["Maxi Talent is for contestants aged 13 and over. Mini Talent is for contestants aged 12 and under. Age is counted on {{AgeCutoffDate}}.","In a duo, if one contestant is 12 or under and the other is 13 or over, the act competes in the Maxi division.","In a group of three or more, if 50 percent or more of the group is aged 13 or over, the group competes in the Maxi division.","No one over the age of 14 may perform in or be part of a Mini division group.","Contestants must be strictly amateur. They must not have been under contract or received payment for their performance. Performers who hold union cards are not eligible. Expense money is not counted as payment.","Contestants must have performed and placed in the top 15 in a County Fair Talent Show or County Talent Contest that is sanctioned by the New York State Fair.","A contestant may take part in only one county competition. Contestants who audition in one county are not eligible to audition in another county. A contestant represents one county only, as a soloist or in a group.","If the members of a group do not all live in the same county, the group competes in the county where most of its performers live. The age rules for groups apply.","Contestants must perform the exact same act that they performed at county level: the same people, routines, music, costumes and clothes. No change of any kind is allowed, including in the Preliminary, Semi-Final and Final. Any change means disqualification.","A contestant may perform at most three times: one solo and two group acts, or three group acts with no solo. Two or more performers count as a group. If this rule is broken, both the contestant and the group are disqualified.","Previous first-place Maxi Final winners and previous first-place Mini Final winners may not enter the same category again. For example, a solo winner cannot return as a soloist the next year. They may perform as part of a duet, trio or group.","Teachers may not compete or perform in their professional talent. For example, a dance teacher cannot compete as a dancer. This does not apply to students on scholarship who help to teach."]},{Key:"registration",Title:"How to enter",Items:["Each county contest chairperson sends the list of the top 15 winners in both the Mini and the Maxi contests to the Talent Showcase within 5 days after the local contest ends, using the spreadsheet provided by the superintendent.","The county entry form must give: name of the act, names of the performers, ages on {{AgeCutoffDate}}, type of act, title of the music if recorded music is used, ONE phone number and ONE email address to be contacted to set the date and time of the Preliminary Competition.","If the act is a group, only one email address is named for registering the act.","If the Talent Showcase has not received the correct information within the allowed time, it may decline the entry.","The Talent Showcase accepts up to, and no more than, the top 15 Mini and the top 15 Maxi acts from county-level preliminary talent competitions. Each entry must be approved by the county and checked with the state fair staff as proof of placement.","Each act uses the link provided by the superintendent to register online, pay the entry fee (this must be done online) and fill in the preference form for the day of the Preliminary.","Every act is scheduled for a day to perform and receives an email confirmation with the date and time of appearance.","Contestants who use recorded music send the music as an MP3 file in the form, or by email to the assistant superintendent ({{AssistantContact}}).","Everyone must report to the Talent Showcase at the scheduled time for sign-in."]},{Key:"fees",Title:"Fees",Items:["The entry fee is {{EntryFee}}, for each act or group. It must be paid online only.","Please make sure the online payment step is completed."]},{Key:"levels",Title:"Preliminary, Semi-Final and Final",Items:["Preliminary contests for Mini and Maxi are held on {{PreliminaryDates}}.","The top 10 place winners from the Mini and Maxi Preliminaries move on to the Semi-Final contest on {{SemiFinalDate}}.","The top 10 place winners from the Mini and Maxi Semi-Finals are eligible to enter the Final contest on {{FinalDate}}.","Mini Preliminary: sign-in starts at {{MiniPrelimSignIn}} in the Talent Showcase Dressing Room and the competition begins at {{MiniPrelimStart}}.","Maxi Preliminary: sign-in starts at {{MaxiPrelimSignIn}} in the Talent Showcase Dressing Room and the competition begins at {{MaxiPrelimStart}}.","Mini Semi-Final: sign-in starts at {{MiniSemiSignIn}} and the competition begins at {{MiniSemiStart}}.","Maxi Semi-Final: sign-in starts at {{MaxiSemiSignIn}} and the competition begins at {{MaxiSemiStart}}.","Mini Final: sign-in starts at {{MiniFinalSignIn}} and the competition begins at {{MiniFinalStart}}.","Maxi Final: sign-in starts at {{MaxiFinalSignIn}} and the competition begins at {{MaxiFinalStart}}."]},{Key:"dates",Title:"Dates",Items:["Preliminaries: {{PreliminaryDates}}.","Semi-Finals: {{SemiFinalDate}}.","Finals: {{FinalDate}}."]},{Key:"venue",Title:"Venue",Items:["The contests are held at the {{Venue}}. Sign-in is in the Talent Showcase Dressing Room."]},{Key:"prizes",Title:"Prizes",Items:["Every contestant receives a participation ribbon.","The top 10 contestants receive an extra ribbon and a commemorative sticker at each level of the competition.","Premium money is paid after the fair to contestants only, for the Final Mini Contest and the Final Maxi Contest: {{FinalPrizes}}.","All awards are given out after the 2025 New York State Fair."]},{Key:"conduct",Title:"Conduct and safety",Items:["No pop-up tents are allowed on the fairgrounds under any circumstance.","No acts that use batons, machetes, knives or similar items are accepted.","No fire is allowed on stage during the competition.","Transport to and from the fair, meals and lodging are the responsibility of the contestant.","Contestants are responsible for any risk, including theft, loss or injury to themselves or their property, while taking part in or visiting the New York State Fair. This includes incidents caused by negligence, intentional acts, accidents, acts of nature or any other reason.","Exhibitors are solely responsible for their property. The New York State Fair and its officers, directors, employees, representatives and assigns are not liable for damages or losses. Exhibitors release them from any liability and agree not to sue them for such risks or damages."]},{Key:"judging",Title:"Judging",Items:["The decision of the judges is final.","To receive the judges' scores, a contestant must request them by email to the superintendent ({{SuperintendentContact}}) before the end of the fair. Give the act name, the date of performance and whether the act is Mini or Maxi. Requests received after the fair is over are not honored, with no exceptions.","The booklet prints no judging criteria or marks."]},{Key:"complaints",Title:"Questions about judging",Items:["Questions about the judges' decisions go to the superintendent ({{SuperintendentContact}})."]}],Documents:[{Title:"2025 Talent Showcase booklet (PDF)",Url:"http://nysfair.ny.gov/wp-content/uploads/2015/08/2025-NYSF-Talent-Showcase-Booklet.pdf"}]},i=[],a=[],o=[{Title:"Talent Act",Source:"2025 Booklet, General Rules",Sections:{About:["A talent act of any kind, performed as a solo, duo, trio or group. The entry form asks for the type of act."],TimeAndFormat:["The time limit is 5 minutes, including trios. Acts are timed. An act that runs over 5 minutes is disqualified."],Rules:null,Allowed:null,NotAllowed:["No acts using batons, machetes, knives or similar items.","No fire on stage."],Judging:null,Points:null,Notes:null},Markdown:`## About this competition
- A talent act of any kind, performed as a solo, duo, trio or group. The entry form asks for the type of act.

## Time and format
- The time limit is 5 minutes, including trios. Acts are timed. An act that runs over 5 minutes is disqualified.

## Not allowed
- No acts using batons, machetes, knives or similar items.
- No fire on stage.`}],r=[],s=[{Key:"PreliminaryDates",Kind:"date",Label:"Preliminary contest days",Value:"2025-08-22 to 2025-08-27 (Friday 8/22, Saturday 8/23, Sunday 8/24, Monday 8/25, Tuesday 8/26, Wednesday 8/27)",Source:"2025 Booklet, schedule"},{Key:"SemiFinalDate",Kind:"date",Label:"Semi-Final day",Value:"2025-08-29",Source:"2025 Booklet, schedule"},{Key:"FinalDate",Kind:"date",Label:"Final day",Value:"2025-08-30",Source:"2025 Booklet, schedule"},{Key:"AgeCutoffDate",Kind:"date",Label:"Date on which age is counted",Value:"2025-07-01",Source:"2025 Booklet, General Rules"},{Key:"MiniPrelimSignIn",Kind:"time",Label:"Mini Preliminary sign-in",Value:"9:00 am",Source:"2025 Booklet, schedule"},{Key:"MiniPrelimStart",Kind:"time",Label:"Mini Preliminary start",Value:"10:30 am",Source:"2025 Booklet, schedule"},{Key:"MaxiPrelimSignIn",Kind:"time",Label:"Maxi Preliminary sign-in",Value:"1:00 pm",Source:"2025 Booklet, schedule"},{Key:"MaxiPrelimStart",Kind:"time",Label:"Maxi Preliminary start",Value:"2:30 pm",Source:"2025 Booklet, schedule"},{Key:"MiniSemiSignIn",Kind:"time",Label:"Mini Semi-Final sign-in",Value:"9:00 am",Source:"2025 Booklet, schedule"},{Key:"MiniSemiStart",Kind:"time",Label:"Mini Semi-Final start",Value:"10:30 am",Source:"2025 Booklet, schedule"},{Key:"MaxiSemiSignIn",Kind:"time",Label:"Maxi Semi-Final sign-in",Value:"2:30 pm",Source:"2025 Booklet, schedule"},{Key:"MaxiSemiStart",Kind:"time",Label:"Maxi Semi-Final start",Value:"4:00 pm",Source:"2025 Booklet, schedule"},{Key:"MiniFinalSignIn",Kind:"time",Label:"Mini Final sign-in",Value:"9:00 am",Source:"2025 Booklet, schedule"},{Key:"MiniFinalStart",Kind:"time",Label:"Mini Final start",Value:"10:30 am",Source:"2025 Booklet, schedule"},{Key:"MaxiFinalSignIn",Kind:"time",Label:"Maxi Final sign-in",Value:"1:00 pm",Source:"2025 Booklet, schedule"},{Key:"MaxiFinalStart",Kind:"time",Label:"Maxi Final start",Value:"2:30 pm",Source:"2025 Booklet, schedule"},{Key:"EntryFee",Kind:"fee",Label:"Entry fee",Value:"USD 15 per act (per group), paid online only",Source:"2025 Booklet, General Rules"},{Key:"FinalPrizes",Kind:"prize",Label:"Premium money for the Final Mini and Final Maxi contests",Value:"1st place ribbon and $500, 2nd place ribbon and $400, 3rd place ribbon and $300, 4th place ribbon and $200, 5th place ribbon and $100, 6th to 10th place ribbon only",Source:"2025 Booklet, premium money"},{Key:"Venue",Kind:"address",Label:"Event venue",Value:{Name:"New York State Fair, Talent Showcase",Address:"Street address not printed in the booklet",City:"",MapUrl:"",Directions:""},Source:"2025 Booklet, schedule"},{Key:"SuperintendentContact",Kind:"contact",Label:"Talent Showcase superintendent",Value:{Name:"Mary Buchmann",Role:"Superintendent, Talent Showcase",Phone:"",WhatsApp:"",Email:"mbuchmann888@gmail.com"},Source:"2025 Booklet, General Rules"},{Key:"AssistantContact",Kind:"contact",Label:"Assistant superintendent (recorded music)",Value:{Name:"Laurie Yager",Role:"Assistant Superintendent, Talent Showcase",Phone:"",WhatsApp:"",Email:"LYAGER888@GMAIL.COM"},Source:"2025 Booklet, General Rules"}],l=[{Claim:"General rules, age limits, the 50 percent group rule, the 5-minute limit, the three-performance cap and county qualification are printed in the booklet.",SourceType:"Primary - the event's own rules document",Source:"New York State Fair 2025 Mini & Maxi Talent Showcase booklet",Url:"http://nysfair.ny.gov/wp-content/uploads/2015/08/2025-NYSF-Talent-Showcase-Booklet.pdf"},{Claim:"The Preliminary, Semi-Final and Final schedule, sign-in times and premium money are printed in the booklet.",SourceType:"Primary - the event's own rules document",Source:"New York State Fair 2025 Mini & Maxi Talent Showcase booklet",Url:"http://nysfair.ny.gov/wp-content/uploads/2015/08/2025-NYSF-Talent-Showcase-Booklet.pdf"},{Claim:"Registration is online, the fee is USD 15 per act, and county chairpersons send the top 15 Mini and top 15 Maxi winners.",SourceType:"Primary - the event's own rules document",Source:"New York State Fair 2025 Mini & Maxi Talent Showcase booklet",Url:"http://nysfair.ny.gov/wp-content/uploads/2015/08/2025-NYSF-Talent-Showcase-Booklet.pdf"}],d={TemplateKey:e,Year:2025,Note:t,Page:n,ParticipantTypes:i,AgeGroups:a,Competitions:o,CompetitionAgeGroups:r,Variables:s,Evidence:l};export{a as AgeGroups,r as CompetitionAgeGroups,o as Competitions,l as Evidence,t as Note,n as Page,i as ParticipantTypes,e as TemplateKey,s as Variables,c as Year,d as default};
